using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Localization;using MiniStore.Application.Services;using MiniStore.Domain.Entities;using MiniStore.Web.Authorization;
namespace MiniStore.Web.Controllers;
public sealed class PurchaseOrdersController(PurchaseOrderService service,IStringLocalizer<SharedResource> localizer):Controller
{
 [HttpGet][PermissionAuthorize("PurchaseOrders.View")]public async Task<IActionResult>Index(PurchaseOrderStatus? status,string? search){ViewBag.Status=status;ViewBag.Search=search;return View(await service.GetAllAsync(status,search));}
 [HttpPost][ValidateAntiForgeryToken][PermissionAuthorize("PurchaseOrders.Create")]public async Task<IActionResult>CreateFromAward(int sourcingEventId){try{var id=await service.CreateFromAwardAsync(sourcingEventId);TempData["NotificationType"]="success";TempData["NotificationMessage"]=localizer["Purchase order created."].Value;return RedirectToAction(nameof(Details),new{id});}catch(Exception e)when(e is ArgumentException or InvalidOperationException){TempData["NotificationType"]="danger";TempData["NotificationMessage"]=localizer[e.Message].Value;return RedirectToAction("Comparison","SupplierQuotations",new{sourcingEventId});}}
 [HttpGet][PermissionAuthorize("PurchaseOrders.View")]public async Task<IActionResult> Details(int id){var dto=await service.GetAsync(id);return dto is null?NotFound():View(dto);}
 [HttpPost][ValidateAntiForgeryToken][PermissionAuthorize("PurchaseOrders.Approve")]public async Task<IActionResult>Approve(int id,byte[] rowVersion){await service.ApproveAsync(id,rowVersion);Notify("Purchase order approved.");return RedirectToAction(nameof(Details),new{id});}
 [HttpPost][ValidateAntiForgeryToken][PermissionAuthorize("PurchaseOrders.Confirm")]public async Task<IActionResult>Confirm(int id,byte[] rowVersion){await service.ConfirmAsync(id,rowVersion);Notify("Purchase order confirmed.");return RedirectToAction(nameof(Details),new{id});}
 [HttpPost][ValidateAntiForgeryToken][PermissionAuthorize("PurchaseOrders.Cancel")]public async Task<IActionResult>Cancel(int id,string reason,byte[] rowVersion){await service.CancelAsync(id,reason,rowVersion);Notify("Purchase order cancelled.");return RedirectToAction(nameof(Details),new{id});}
 [HttpPost][ValidateAntiForgeryToken][PermissionAuthorize("PurchaseOrders.Close")]public async Task<IActionResult>CloseRemaining(int id,string reason,byte[] rowVersion){try{await service.CloseRemainingAsync(id,reason,rowVersion);Notify("Purchase order remaining quantity closed.");}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Notify("danger",e.Message);}return RedirectToAction(nameof(Details),new{id});}
 [HttpPost][ValidateAntiForgeryToken][PermissionAuthorize("PurchaseOrders.Reopen")]public async Task<IActionResult>Reopen(int id,string reason,byte[] rowVersion){try{await service.ReopenAsync(id,reason,rowVersion);Notify("Purchase order reopened.");}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Notify("danger",e.Message);}return RedirectToAction(nameof(Details),new{id});}
 private void Notify(string message){TempData["NotificationType"]="success";TempData["NotificationMessage"]=localizer[message].Value;}
 private void Notify(string type,string message){TempData["NotificationType"]=type;TempData["NotificationMessage"]=localizer[message].Value;}
}
